import {hasSensitive} from './admin-permissions.mjs';
import {chinaDate,ContractError} from './cloud-contract.mjs';
const count=v=>{if(!Number.isSafeInteger(v)||v<0)throw new ContractError('提醒数量暂不完整，请刷新核对。');return v;};
export function reminderDates(today=chinaDate()){const d=new Date(today+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==today)throw new ContractError();const until=new Date(d);until.setUTCDate(until.getUTCDate()+7);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-1);return {today,until:until.toISOString().slice(0,10),month:d.toISOString().slice(0,7)};}
export function businessReminderSources(api,user,signal,dates=reminderDates()){const sources=[];
 if(hasSensitive(user,'resources'))sources.push({key:'cards',label:'手机卡到期、充值与关联核对',hint:'日期提醒含未来7天；按手机卡计数',unit:'张',action:'cards',load:()=>api.cardReminders({until:dates.until},signal).then(v=>count(v.total))},{key:'stock',label:'包材待补货',hint:'按达到补货阈值的库存归属计数',unit:'项',action:'stock',load:()=>api.warehouseReorderAlerts(0,signal).then(v=>count(v.total))});
 if(hasSensitive(user,'personnel'))sources.push({key:'corrections',label:'补卡待审核',hint:'当前全部待审核申请',unit:'笔',action:'attendance',load:()=>api.attendanceCorrections({view:'team',status:'pending',offset:0},signal).then(v=>count(v.total))},{key:'leaves',label:'请假待审核',hint:'当前全部待审核申请',unit:'笔',action:'attendance',load:()=>api.leaveList({view:'team',status:'pending',offset:0},signal).then(v=>count(v.total))});
 if(hasSensitive(user,'finance'))sources.push({key:'finance',label:dates.month+' 经营月度待核对',hint:'上月经营来源检查；不代表利润或待付款金额',unit:'项',action:'finance',month:dates.month,load:()=>api.financeMonthReview({month:dates.month,section:'all',severity:'all',offset:0},signal).then(v=>count(v.counts.blocker)+count(v.counts.review))});
 return sources;
}
export function createBusinessReminders({api,h,getUser}){let revision=0;
 async function render(container,signal){if(!container)return;const run=++revision,user=getUser(),dates=reminderDates(),sources=businessReminderSources(api,user,signal,dates);container.innerHTML='<div class="reminder-heading"><span class="section-kicker">BUSINESS REMINDERS</span><button type="button" class="text-button" data-reminders-refresh>刷新</button></div><h2>经营提醒</h2><p class="muted">当前业务状态，不随左侧工作日期切换。</p><div data-reminder-groups></div><p class="muted reminder-date">核对日期 '+h(dates.today)+'</p>';const results=container.querySelector('[data-reminder-groups]');
 const action=s=>s.action==='cards'?`<button class="text-button" data-open-phone-cards data-phone-reminders="true" data-phone-until="${h(dates.until)}">查看手机卡 →</button>`:s.action==='stock'?'<button class="text-button" data-open-warehouse-reorder>查看待补货 →</button>':s.action==='finance'?`<button class="text-button" data-finance-review="${h(s.month)}">查看月度来源 →</button>`:'<a class="text-button" href="#attendance">前往考勤审核 →</a>';
 const values=new Map(),paint=()=>{if(signal.aborted||run!==revision||getUser()?.id!==user?.id)return;results.innerHTML=sources.length?sources.map(s=>{const state=values.get(s.key);return `<article class="business-reminder-row"><b>${h(s.label)}</b><p>${!state?'正在核对…':state.error?'暂未读取，待核对':`<strong>${state.count}</strong> ${h(s.unit)}${state.count===0?' · 当前无此类待处理':''}`}</p><small>${h(state?.error?'读取未完成，不计为零；可刷新或进入原模块核对。':s.hint)}</small>${action(s)}</article>`;}).join(''):'<p class="muted">当前账号没有经营管理提醒权限。个人事项与考勤仍在原入口处理。</p>';};paint();container.querySelector('[data-reminders-refresh]').onclick=()=>render(container,signal);await Promise.allSettled(sources.map(async source=>{try{const n=await source.load();values.set(source.key,{count:n});}catch{values.set(source.key,{error:true});}paint();}));}
 return {render};
}
